local card={api_version=1,id="EX1_165",name="Druid of the Claw",text="[x]<b>Choose One -</b> Transform\ninto a 7/6 with <b>Rush</b>;\nor a 4/9 with <b>Taunt</b>.",set="EXPERT1",type="minion",class="druid",rarity="common",cost=6,attack=4,health=6,keywords={"choose_one"}}
function card.on_choose_one(ctx,self)ctx:choose_options(ctx:controller(self),"Choose One",{{card_id="EX1_165a",label="7/6 with Rush"},{card_id="EX1_165b",label="4/9 with Taunt"}},"chosen")end
function card.chosen(ctx,self,c)cardlib.effects.transform(ctx, self,c=="EX1_165a" and "EX1_165t1"or"EX1_165t2")end
function card.on_choose_multiple(ctx,self)cardlib.effects.transform(ctx, self,"EX1_165t1");cardlib.effects.buff(ctx, self,0,3);cardlib.effects.grant_keyword(ctx, self,"taunt")end
card.tokens={{id="EX1_165a", rarity="common",name="Cat Form",text="<b>Rush</b>",set="EXPERT1",type="minion",class="druid",collectible=false,cost=6,attack=7,health=6,tags={"beast"},keywords={"rush"}},{id="EX1_165b",rarity="common",name="Bear Form",text="<b>Taunt</b>",set="EXPERT1",type="minion",class="druid",collectible=false,cost=6,attack=4,health=9,tags={"beast"},keywords={"taunt"}},{id="EX1_165t1", rarity = "common",name="Druid of the Claw",text="<b>Rush</b>",set="EXPERT1",type="minion",class="druid",collectible=false,cost=6,attack=7,health=6,tags={"beast"},keywords={"rush"}},{id="EX1_165t2", rarity = "common",name="Druid of the Claw",text="<b>Taunt</b>",set="EXPERT1",type="minion",class="druid",collectible=false,cost=6,attack=4,health=9,tags={"beast"},keywords={"taunt"}}}
return card
